<script setup lang="ts">
import {ref,watch} from 'vue';import {useRoute} from 'vue-router';import {api,mutate,can,text,opts,useTask,type DTO} from './shared';import {useForm} from './forms';import TaskForm from './TaskForm.vue';import PageState from './PageState.vue';
const route=useRoute(),row=ref<DTO<'Stage2CatalogView'>>(),{busy,error,run}=useTask(),{form,open}=useForm();
async function load(){await run(async()=>{row.value=await api.get<DTO<'Stage2CatalogView'>>(`/directory/${route.params.kind}/${route.params.id}`);});}watch(()=>route.fullPath,load,{immediate:true});
function edit(){const r=row.value!;open({title:'修订'+text(r.kind),fields:r.kind==='identity'?[{key:'label',label:'辨识名称',initial:r.name},{key:'provider',label:'提供方',initial:r.provider??''}]:[{key:'name',label:'名称',required:true,initial:r.name},...(r.kind==='platform'?[{key:'website',label:'官方网站',type:'url',initial:r.website??''}]:[{key:'description',label:'说明',type:'textarea',initial:r.description??''}]),{key:'status',label:'状态',options:opts(['active','inactive','unknown']),initial:r.status}],onSubmit:async v=>{await mutate(r.kind==='identity'?`/contact-identities/${r.id}`:`/directory/${r.kind}/${r.id}`,{expected_version:r.version,...Object.fromEntries(Object.entries(v).map(([k,x])=>[k,x||null]))},'PATCH');await load();}});}
</script>
<template><header class="page-heading"><div><RouterLink to="/resources" class="text-link text-xs">← 资源清单</RouterLink><h1 class="mt-2">{{row?.name??'目录详情'}}</h1><p>目录对象 · {{text(row?.kind)}} · 不生成虚构的资源记录</p></div><div v-if="row" class="flex flex-wrap gap-2"><RouterLink :to="{path:'/asset-map',query:{kind:row.kind,id:row.id}}" class="btn-secondary">查看关系图</RouterLink><button v-if="can('catalog.write')" class="btn-primary" @click="edit">修订资料</button></div></header><PageState :busy="busy" :error="error" @retry="load"/><section v-if="row" class="feishu-section p-4"><dl class="detail-grid"><div><dt>状态</dt><dd>{{text(row.status)}}</dd></div><div v-if="row.website"><dt>官方网站</dt><dd><a v-if="/^https?:\/\//.test(row.website)" :href="row.website" target="_blank" rel="noopener noreferrer" class="text-link">{{row.website}}</a></dd></div><div v-if="row.registration_identifier"><dt>主体标识</dt><dd>{{row.registration_identifier}}</dd></div><div v-if="row.masked_value"><dt>身份内容（脱敏）</dt><dd>{{row.masked_value}}</dd></div><div v-if="row.identity_kind"><dt>身份类型 / 归属</dt><dd>{{text(row.identity_kind)}} / {{text(row.ownership)}}</dd></div><div v-if="row.description"><dt>说明</dt><dd>{{row.description}}</dd></div></dl><p class="mt-4 border-t pt-3 text-xs text-gray-500">关联资源从同源资产地图查看；目录修订不会变更已确认的资源责任或使用权限。</p></section><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></template>
